import{_ as s,o as a,c as i,ah as n}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Infirmerie","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/infirmerie/index.md","filePath":"src/guide/infirmerie/index.md"}'),r={name:"guide/infirmerie/index.md"};function t(o,e,l,u,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="infirmerie" tabindex="-1">Infirmerie <a class="header-anchor" href="#infirmerie" aria-label="Permalink to &quot;Infirmerie&quot;">​</a></h1><p>En tant que responsable de l&#39;infirmerie, vous enregistrez dans ERA chaque passage d&#39;un élève à l&#39;infirmerie : le motif, les soins donnés et l&#39;issue (retour en classe ou renvoi à la maison). L&#39;espace <strong>Services aux élèves</strong> vous donne accès à une page, <strong>Passages à l&#39;infirmerie</strong>, qui liste tous les passages et permet d&#39;en créer, consulter ou modifier.</p><div class="info custom-block"><p class="custom-block-title">Un seul site</p><p>Si votre fiche employé indique un site, ERA ne vous montre que ce site : élèves, classes, passages à l&#39;infirmerie et tableau de bord. Une fiche d&#39;un autre site n&#39;apparaît pas et ne s&#39;ouvre pas. Sans site sur votre fiche, vous voyez tout l&#39;établissement. Le site se règle par l&#39;administrateur, dans la <a href="/era-guide/guide/admin/personnel-utilisateurs.html#gerer-les-fiches-et-contrats-du-personnel">fiche employé</a>.</p></div><h2 id="consulter-les-passages" tabindex="-1">Consulter les passages <a class="header-anchor" href="#consulter-les-passages" aria-label="Permalink to &quot;Consulter les passages&quot;">​</a></h2><p>La page <strong>Passages à l&#39;infirmerie</strong> liste les passages enregistrés, avec la date et l&#39;heure, l&#39;élève concerné, le motif et l&#39;issue (affichée sous forme d&#39;étiquette : <strong>Retour en classe</strong> ou <strong>Renvoyé à la maison</strong>, cette dernière mise en évidence en rouge). Vous pouvez rechercher un passage par nom d&#39;élève avec le champ de recherche en haut de la page. Cliquez sur une ligne pour ouvrir un panneau récapitulatif avec la date et l&#39;heure, le motif et l&#39;issue.</p><h2 id="enregistrer-un-nouveau-passage" tabindex="-1">Enregistrer un nouveau passage <a class="header-anchor" href="#enregistrer-un-nouveau-passage" aria-label="Permalink to &quot;Enregistrer un nouveau passage&quot;">​</a></h2><ol><li>Cliquez sur <strong>Nouveau passage</strong> en haut de la page <strong>Passages à l&#39;infirmerie</strong>.</li><li>Sélectionnez l&#39;<strong>Élève</strong> concerné.</li><li>Renseignez la <strong>Date et heure</strong> du passage.</li><li>Décrivez le <strong>Motif</strong> de la visite (ce qui amène l&#39;élève à l&#39;infirmerie).</li><li>Le champ <strong>Soins donnés</strong> est optionnel : décrivez-y les soins apportés, si applicable.</li><li>Choisissez l&#39;<strong>Issue</strong> : <strong>Retour en classe</strong> si l&#39;élève repart en cours, ou <strong>Renvoyé à la maison</strong> s&#39;il doit rentrer chez lui.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Si vous choisissez l&#39;issue <strong>Renvoyé à la maison</strong>, les parents ou tuteurs de l&#39;élève reçoivent automatiquement une notification indiquant le motif et l&#39;heure du passage — vous n&#39;avez rien d&#39;autre à faire de votre côté.</p><h2 id="consulter-et-modifier-un-passage-existant" tabindex="-1">Consulter et modifier un passage existant <a class="header-anchor" href="#consulter-et-modifier-un-passage-existant" aria-label="Permalink to &quot;Consulter et modifier un passage existant&quot;">​</a></h2><ol><li>Depuis la page <strong>Passages à l&#39;infirmerie</strong>, cliquez sur <strong>Modifier</strong> sur la ligne du passage concerné (ou ouvrez d&#39;abord le panneau récapitulatif en cliquant sur la ligne, puis cliquez sur <strong>Modifier</strong> depuis ce panneau).</li><li>Mettez à jour l&#39;élève, la date et l&#39;heure, le motif, les soins donnés ou l&#39;issue selon les besoins.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><p>Si vous changez l&#39;issue en <strong>Renvoyé à la maison</strong> alors qu&#39;elle ne l&#39;était pas déjà, les parents ou tuteurs de l&#39;élève sont notifiés au moment de l&#39;enregistrement des modifications, comme pour un nouveau passage.</p><h3 id="supprimer-un-passage" tabindex="-1">Supprimer un passage <a class="header-anchor" href="#supprimer-un-passage" aria-label="Permalink to &quot;Supprimer un passage&quot;">​</a></h3><p>Depuis la page <strong>Passages à l&#39;infirmerie</strong>, cliquez sur <strong>Supprimer</strong> sur la ligne du passage concerné, puis confirmez dans la fenêtre qui s&#39;affiche. Cette action supprime définitivement l&#39;enregistrement et ne peut pas être annulée.</p><h2 id="confidentialite-des-passages" tabindex="-1">Confidentialité des passages <a class="header-anchor" href="#confidentialite-des-passages" aria-label="Permalink to &quot;Confidentialité des passages&quot;">​</a></h2><p>Le motif et les soins donnés sont des données de santé : ERA les enregistre <strong>chiffrés</strong>, illisibles pour qui accéderait directement à la base de données. Le journal d&#39;activité n&#39;en garde aucune copie : il indique seulement qu&#39;ils ont changé. Chaque ouverture de la liste des passages ou d&#39;un passage y est inscrite.</p><h2 id="les-dossiers-medicaux" tabindex="-1">Les dossiers médicaux <a class="header-anchor" href="#les-dossiers-medicaux" aria-label="Permalink to &quot;Les dossiers médicaux&quot;">​</a></h2><p>Si l&#39;établissement a activé la gestion documentaire, l&#39;espace <strong>Documents</strong> vous donne accès aux <strong>dossiers médicaux</strong> des élèves : par défaut, vous seul (avec l&#39;administrateur) les consultez, les déposez et les validez. Chaque ouverture d&#39;un dossier médical est inscrite au journal d&#39;activité. Voir <a href="/era-guide/guide/gestion-documentaire/">Gestion documentaire</a>.</p>',17)])])}const m=s(r,[["render",t]]);export{p as __pageData,m as default};
